// Parse LEDES 1998B (pipe-delimited). Returns one item per invoice with line_items array.
// Spec: https://ledes.org/ledes-1998b/
const raw = $json.data || $input.item.json.data || $input.item.json.body || '';
const lines = raw.split(/\r?\n/).filter(Boolean);
if (lines.length < 2) {
  return [{ json: { invoice_id: $('Split Invoices').item.json.id, line_items: [], parse_error: 'empty_or_malformed_ledes' } }];
}
const headers = lines[0].split('|').map(h => h.trim());
const idx = (name) => headers.indexOf(name);
const col = {
  invoice_number: idx('INVOICE_NUMBER'),
  matter_id: idx('CLIENT_MATTER_ID'),
  law_firm_id: idx('LAW_FIRM_ID'),
  timekeeper_id: idx('TIMEKEEPER_ID'),
  timekeeper_name: idx('TIMEKEEPER_NAME'),
  timekeeper_classification: idx('TIMEKEEPER_CLASSIFICATION'),
  rate: idx('LINE_ITEM_UNIT_COST'),
  units: idx('LINE_ITEM_NUMBER_OF_UNITS'),
  task_code: idx('LINE_ITEM_TASK_CODE'),
  activity_code: idx('LINE_ITEM_ACTIVITY_CODE'),
  date: idx('LINE_ITEM_DATE'),
  description: idx('LINE_ITEM_DESCRIPTION'),
  total: idx('LINE_ITEM_TOTAL')
};
const items = [];
for (let i = 1; i < lines.length; i++) {
  const cells = lines[i].split('|');
  if (cells.length < headers.length) continue;
  items.push({
    invoice_number: cells[col.invoice_number],
    matter_id: cells[col.matter_id],
    law_firm_id: cells[col.law_firm_id],
    timekeeper_id: cells[col.timekeeper_id],
    timekeeper_name: cells[col.timekeeper_name],
    timekeeper_classification: cells[col.timekeeper_classification],
    rate: parseFloat(cells[col.rate]) || 0,
    units: parseFloat(cells[col.units]) || 0,
    task_code: cells[col.task_code],
    activity_code: cells[col.activity_code],
    date: cells[col.date],
    description: (cells[col.description] || '').trim(),
    total: parseFloat(cells[col.total]) || 0
  });
}
return [{
  json: {
    invoice_id: $('Split Invoices').item.json.id,
    matter_id: items[0]?.matter_id,
    law_firm_id: items[0]?.law_firm_id,
    invoice_number: items[0]?.invoice_number,
    line_items: items,
    line_count: items.length,
    invoice_total: items.reduce((s, x) => s + (x.total || 0), 0)
  }
}];

// Apply deterministic billing-guideline checks. Output: per-line flags + invoice rollup.
const inv = $('Parse LEDES').item.json;
const ctx = $json;
const approved = new Map((ctx.approved_timekeepers || []).map(t => [t.timekeeper_id, t]));
const gl = ctx.guidelines || {};
const vagueKeywords = (gl.vague_keywords || ['attention to', 'work on', 'review of', 'various', 'general']);
const minBlockUnits = gl.block_billing_min_units ?? 4.0;
const noTravelClass = new Set(gl.no_travel_class || ['Partner']);
const flags = [];
for (const li of inv.line_items) {
  const tkApproved = approved.get(li.timekeeper_id);
  if (!tkApproved) {
    flags.push({ kind: 'unapproved_timekeeper', timekeeper_id: li.timekeeper_id, line: li, severity: 0.6 });
  } else {
    const cap = (tkApproved.max_rate_cents || 0) / 100;
    if (cap > 0 && li.rate > cap) {
      flags.push({ kind: 'rate_over_card', actual_rate: li.rate, card_rate: cap, line: li, severity: 0.5 });
    }
  }
  if (li.units >= minBlockUnits && /[;,\.]/.test(li.description) === false && li.description.split(' ').length < 8) {
    flags.push({ kind: 'block_billing', units: li.units, line: li, severity: 0.4 });
  }
  const desc = (li.description || '').toLowerCase();
  if (vagueKeywords.some(k => desc.startsWith(k.toLowerCase()) || desc === k.toLowerCase())) {
    flags.push({ kind: 'vague_description', line: li, severity: 0.3 });
  }
  if (li.timekeeper_classification && noTravelClass.has(li.timekeeper_classification) && /travel|commute|airport/i.test(li.description)) {
    flags.push({ kind: 'partner_travel_billed', line: li, severity: 0.5 });
  }
}
const rule_value_cents = Math.round(
  flags.reduce((s, f) => {
    if (f.kind === 'rate_over_card') return s + (f.actual_rate - f.card_rate) * f.line.units * 100;
    if (f.kind === 'block_billing') return s + (f.line.total * 0.10) * 100;
    if (f.kind === 'partner_travel_billed') return s + (f.line.total * 0.50) * 100;
    if (f.kind === 'vague_description') return s + (f.line.total * 0.05) * 100;
    return s;
  }, 0)
);
return [{
  json: {
    invoice_id: inv.invoice_id,
    invoice_number: inv.invoice_number,
    matter_id: inv.matter_id,
    law_firm_id: inv.law_firm_id,
    matter: ctx.matter,
    invoice_total: inv.invoice_total,
    rule_flags: flags,
    rule_flag_count: flags.length,
    rule_value_cents,
    line_items: inv.line_items
  }
}];

