// Combine rule-based hits and Claude's flags into a single per-invoice score and routing decision.
const rb = $('Rule-Based Checks').item.json;
let aiFlags = [];
try {
  const text = $json.content?.[0]?.text || '[]';
  aiFlags = JSON.parse(text);
  if (!Array.isArray(aiFlags)) aiFlags = [];
} catch (e) {
  aiFlags = [];
}
const aiSeverityMax = aiFlags.reduce((m, f) => Math.max(m, Number(f.severity) || 0), 0);
const ruleSeverityMax = rb.rule_flags.reduce((m, f) => Math.max(m, Number(f.severity) || 0), 0);
const ruleValueShare = (rb.invoice_total > 0) ? (rb.rule_value_cents / 100) / rb.invoice_total : 0;
let decision = 'auto_approve';
let reason = 'no flags';
if (aiSeverityMax >= 0.8 || ruleValueShare >= 0.15) {
  decision = 'escalate_director';
  reason = aiSeverityMax >= 0.8 ? 'severe_ai_anomaly' : 'large_rule_value_share';
} else if (aiFlags.length > 0 || ruleSeverityMax >= 0.5) {
  decision = 'reviewer_queue';
  reason = aiFlags.length > 0 ? 'ai_flags_present' : 'rule_severity_above_threshold';
} else if (rb.rule_flag_count > 0) {
  decision = 'auto_deduct';
  reason = 'low_value_rule_flags_only';
}
return [{
  json: {
    ...rb,
    ai_flags: aiFlags,
    ai_flag_count: aiFlags.length,
    decision,
    reason,
    score: { aiSeverityMax, ruleSeverityMax, ruleValueShare }
  }
}];

